# Optional genuinely nominal conditional synthesis ---------------------------
# The target is generated by sampling a fitted multinomial regression P(Y|X),
# rather than interpreting its categories as thresholded intervals of one
# latent Gaussian coordinate. Predictor generation and missingness remain
# handled by the fitted copula. This deliberately supports ONE nominal target.
# The fitted regression retains information from confidential training data.

.fit_nominal <- function(df, settings) {
  target <- settings$nominal_target
  if (is.null(target)) return(NULL)
  y <- df[[target]]
  ok <- !is.na(y)
  predictors <- setdiff(names(df), target)
  if (!length(predictors) || sum(ok) < 40L) return(NULL)
  # First-occurrence ordering is independent of the *names* of categories
  # for an otherwise identical, fixed-row-order training dataset.
  categories <- unique(as.character(y[ok]))
  if (length(categories) < 2L || length(categories) > 20L) return(NULL)
  enc <- .hybrid_encode(df[predictors])
  x_obs <- enc$data[ok, , drop = FALSE]
  response <- factor(as.character(y[ok]), levels = categories)
  # Candidate models: linear terms and, if requested, natural splines for
  # the numeric predictors. The one with the smaller AIC is kept, so spline
  # terms are used only when the data support the extra parameters (with
  # (near-)separated classes the linear logit is better determined).
  max_df <- as.integer(settings$nominal_spline_df %||% 3L)
  candidates <- unique(c(if (max_df >= 2L) max_df, 0L))
  fits <- lapply(candidates, function(sdf) {
    splines <- .nominal_spline_specs(x_obs, sdf)
    if (sdf > 0L && !length(splines)) return(NULL)  # no numeric predictor
    tr <- .nominal_design(x_obs, splines)
    tr$.response <- response
    model <- tryCatch(
      suppressWarnings(nnet::multinom(.response ~ ., data = tr, trace = FALSE,
                                      decay = settings$nominal_decay,
                                      maxit = settings$nominal_maxit,
                                      model = FALSE)),
      error = identity)
    if (inherits(model, "error") || !isTRUE(model$convergence == 0L)) return(NULL)
    list(spline_df = sdf, splines = splines, model = model, aic = model$AIC)
  })
  aic <- data.frame(spline_df = candidates,
                    converged = !vapply(fits, is.null, logical(1)),
                    aic = vapply(fits, function(f) if (is.null(f)) NA_real_ else f$aic,
                                 numeric(1)))
  fits <- fits[!vapply(fits, is.null, logical(1))]
  if (!length(fits)) return(NULL)  # Sparse strata keep the baseline copula output.
  best <- fits[[which.min(vapply(fits, `[[`, numeric(1), "aic"))]]
  splines <- best$splines
  model <- best$model
  list(target = target, predictors = predictors, encoder = enc$specs,
       splines = splines, spline_df = best$spline_df, selection = aic,
       model = model, categories = categories, engine = "multinomial")
}

# Natural cubic spline bases for the numeric predictors of the multinomial
# model, so that category probabilities can depend nonlinearly (e.g.
# non-monotonically) on them. Missingness indicators and numeric columns
# with fewer than five distinct values enter linearly. Knots are placed at
# quantiles of the observed training values and stored with the model.
.nominal_spline_specs <- function(encoded, df_spline) {
  df_spline <- as.integer(df_spline)
  out <- list()
  if (df_spline < 2L) return(out)
  for (nm in names(encoded)) {
    x <- encoded[[nm]]
    if (is.factor(x) || grepl("_missing$", nm)) next
    if (length(unique(x)) < 5L) next
    probs <- seq_len(df_spline - 1L) / df_spline
    knots <- unique(stats::quantile(x, probs, names = FALSE, type = 7))
    boundary <- range(x)
    knots <- knots[knots > boundary[1L] & knots < boundary[2L]]
    out[[nm]] <- list(knots = knots, boundary = boundary)
  }
  out
}

.nominal_design <- function(encoded, splines) {
  if (is.null(splines) || !length(splines)) return(encoded)
  for (nm in names(splines)) {
    sp <- splines[[nm]]
    basis <- splines::ns(encoded[[nm]], knots = sp$knots, Boundary.knots = sp$boundary)
    basis <- unclass(basis)[, , drop = FALSE]
    attributes(basis) <- list(dim = dim(basis))
    colnames(basis) <- paste0(nm, "_ns", seq_len(ncol(basis)))
    encoded[[nm]] <- NULL
    encoded <- cbind(encoded, as.data.frame(basis))
  }
  encoded
}

.generate_nominal <- function(model, df) {
  enc <- .hybrid_encode(df[model$predictors], model$encoder)
  n <- nrow(df)
  if (!n) return(character(0L))
  pred <- stats::predict(model$model, newdata = .nominal_design(enc$data, model$splines),
                         type = "probs")
  k <- length(model$categories)
  if (k == 2L && is.null(dim(pred))) {
    # nnet::multinom returns P(second class) for a binomial fit.
    pred <- cbind(1 - as.numeric(pred), as.numeric(pred))
  } else if (is.null(dim(pred))) {
    pred <- matrix(as.numeric(pred), nrow = n, ncol = k, byrow = TRUE)
  }
  pred <- as.matrix(pred)
  if (nrow(pred) != n || ncol(pred) != k || any(!is.finite(pred)) ||
      any(pred < 0)) stop("Invalid nominal category probabilities.", call. = FALSE)
  # nnet's prediction columns follow the response's training factor levels.
  rs <- rowSums(pred)
  if (any(rs <= 0)) stop("Nominal category probabilities sum to zero.", call. = FALSE)
  pred <- pred / rs
  uniform <- stats::runif(n)
  cum <- t(apply(pred, 1L, cumsum))
  # apply() can simplify an n=1 result unexpectedly; restore dimensions.
  cum <- matrix(cum, nrow = n, ncol = k)
  # Rowwise categorical inverse CDF. Avoid calling sample() for every row.
  idx <- 1L + rowSums(uniform >= cum[, -k, drop = FALSE])
  model$categories[idx]
}
